//! Markup parity with `@santi020k/lumen-react`.
//!
//! `tests/fixtures/react-markup.json` holds `renderToStaticMarkup` output from lumen-react,
//! generated by `pnpm run generate:dioxus-fixtures`. Each case below renders the same component
//! with Dioxus SSR, and the two documents must match after normalization: attribute order,
//! quoting, boolean attribute spelling, and whitespace inside `style` are ignored.

use std::collections::BTreeMap;

use dioxus::prelude::*;
use lumen_dioxus::prelude::*;

const FIXTURES: &str = include_str!("fixtures/react-markup.json");

const BOOLEAN_ATTRIBUTES: &[&str] = &["checked", "disabled", "hidden", "readonly", "required"];
const VOID_ELEMENTS: &[&str] = &["br", "hr", "img", "input", "link", "meta"];

#[derive(Debug, PartialEq)]
enum Token {
    Open(String, Vec<(String, String)>),
    Close(String),
    Text(String),
}

fn decode_entities(text: &str) -> String {
    text.replace("&quot;", "\"")
        .replace("&#x27;", "'")
        .replace("&#39;", "'")
        .replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&amp;", "&")
}

fn normalize_value(name: &str, value: String) -> String {
    if BOOLEAN_ATTRIBUTES.contains(&name) && (value.is_empty() || value == "true") {
        return String::new();
    }

    if name == "style" {
        let compact: String = value.chars().filter(|c| !c.is_whitespace()).collect();
        return compact.trim_end_matches(';').to_string();
    }

    value
}

/// Reads one tag body (between `<` and `>`) with a single linear scan.
fn parse_tag(body: &str) -> Token {
    let body = body.trim_end_matches('/').trim();

    if let Some(name) = body.strip_prefix('/') {
        return Token::Close(name.trim().to_ascii_lowercase());
    }

    let chars: Vec<char> = body.chars().collect();
    let mut index = 0;
    let mut name = String::new();

    while index < chars.len() && !chars[index].is_whitespace() {
        name.push(chars[index]);
        index += 1;
    }

    let mut attributes = Vec::new();

    loop {
        while index < chars.len() && chars[index].is_whitespace() {
            index += 1;
        }

        if index >= chars.len() {
            break;
        }

        let mut key = String::new();

        while index < chars.len() && chars[index] != '=' && !chars[index].is_whitespace() {
            key.push(chars[index]);
            index += 1;
        }

        let mut value = String::new();

        if index < chars.len() && chars[index] == '=' {
            index += 1;

            if index < chars.len() && (chars[index] == '"' || chars[index] == '\'') {
                let quote = chars[index];
                index += 1;

                while index < chars.len() && chars[index] != quote {
                    value.push(chars[index]);
                    index += 1;
                }

                index += 1;
            } else {
                while index < chars.len() && !chars[index].is_whitespace() {
                    value.push(chars[index]);
                    index += 1;
                }
            }
        }

        let key = key.to_ascii_lowercase();
        let value = normalize_value(&key, decode_entities(&value));
        attributes.push((key, value));
    }

    attributes.sort();
    Token::Open(name.to_ascii_lowercase(), attributes)
}

fn tokenize(html: &str) -> Vec<Token> {
    let mut tokens = Vec::new();
    let mut rest = html;

    while !rest.is_empty() {
        if let Some(after) = rest.strip_prefix('<') {
            let end = after.find('>').expect("unterminated tag");
            let token = parse_tag(&after[..end]);

            if let Token::Open(name, _) = &token {
                let is_void = VOID_ELEMENTS.contains(&name.as_str());
                tokens.push(token);

                if is_void {
                    rest = &after[end + 1..];
                    // Some serializers also emit a closing tag for void elements.
                    continue;
                }
            } else if let Token::Close(name) = &token {
                if VOID_ELEMENTS.contains(&name.as_str()) {
                    rest = &after[end + 1..];
                    continue;
                }

                tokens.push(token);
            }

            rest = &after[end + 1..];
        } else {
            let end = rest.find('<').unwrap_or(rest.len());
            let text = decode_entities(&rest[..end]);

            if !text.is_empty() {
                tokens.push(Token::Text(text));
            }

            rest = &rest[end..];
        }
    }

    tokens
}

fn fixtures() -> BTreeMap<String, String> {
    serde_json::from_str(FIXTURES).expect("react-markup.json is a flat object of strings")
}

fn assert_parity(name: &str, element: Element) {
    let fixtures = fixtures();
    let react = fixtures
        .get(name)
        .unwrap_or_else(|| panic!("missing fixture {name}; run pnpm run generate:dioxus-fixtures"));
    let dioxus = dioxus_ssr::render_element(element);

    assert_eq!(
        tokenize(&dioxus),
        tokenize(react),
        "\n{name} differs from lumen-react\n dioxus: {dioxus}\n  react: {react}\n"
    );
}

#[test]
fn every_fixture_has_a_dioxus_case() {
    let names: Vec<String> = fixtures().into_keys().collect();
    let covered = cases()
        .into_iter()
        .map(|(name, _)| name)
        .collect::<Vec<_>>();

    for name in names {
        assert!(
            covered.contains(&name.as_str()),
            "fixture {name} has no Dioxus case"
        );
    }
}

#[test]
fn dioxus_markup_matches_lumen_react() {
    for (name, element) in cases() {
        assert_parity(name, element);
    }
}

