#[test]
fn invalid_field_wires_control_and_error() {
    let html = dioxus_ssr::render_element(rsx! {
        Field { control_id: "name", invalid: true,
            Input { id: "name" }
            FieldError { message: "Required." }
        }
    });

    assert!(html.contains(r#"aria-invalid="true""#), "{html}");
    assert!(html.contains(r#"aria-describedby="name-error""#), "{html}");
    assert!(html.contains(r#"id="name-error""#), "{html}");
}

#[test]
fn checkbox_and_switch_render_as_aria_buttons() {
    let html = dioxus_ssr::render_element(rsx! {
        Checkbox { default_checked: true, aria_label: "Remember me", name: "remember" }
        Checkbox { indeterminate: true, aria_label: "All rows" }
        Switch { aria_label: "Notifications", disabled: true }
    });

    let tokens = tokenize(&html);
    let opens: Vec<&Vec<(String, String)>> = tokens
        .iter()
        .filter_map(|token| match token {
            Token::Open(name, attributes) if name == "button" => Some(attributes),
            _ => None,
        })
        .collect();

    let get = |attributes: &[(String, String)], key: &str| {
        attributes
            .iter()
            .find(|(name, _)| name == key)
            .map(|(_, value)| value.clone())
    };

    assert_eq!(opens.len(), 3, "{html}");
    assert_eq!(get(opens[0], "role").as_deref(), Some("checkbox"));
    assert_eq!(get(opens[0], "aria-checked").as_deref(), Some("true"));
    assert_eq!(get(opens[0], "class").as_deref(), Some("ui-checkbox"));
    assert_eq!(get(opens[1], "aria-checked").as_deref(), Some("mixed"));
    assert_eq!(get(opens[2], "role").as_deref(), Some("switch"));
    assert_eq!(get(opens[2], "aria-checked").as_deref(), Some("false"));
    assert_eq!(get(opens[2], "disabled").as_deref(), Some(""));
    assert!(
        html.contains(r#"name="remember""#),
        "checked box submits its value: {html}"
    );
}

#[test]
fn stylesheet_has_aria_state_aliases() {
    for selector in [
        r#".ui-checkbox[aria-checked="true"]"#,
        r#".ui-checkbox[aria-checked="mixed"]"#,
        r#".ui-switch[aria-checked="true"]"#,
    ] {
        assert!(
            lumen_dioxus::LUMEN_CSS.contains(selector),
            "missing {selector}"
        );
    }

    assert!(
        !lumen_dioxus::LUMEN_CSS.contains("@import"),
        "stylesheet must be self-contained"
    );
}
